// Redis commands demonstrated via ioredis (Node.js client)
// npm install ioredis   (works the same against Redis or Valkey)

import Redis from 'ioredis';
import { randomUUID } from 'node:crypto';

const redis = new Redis({ host: 'localhost', port: 6379 });
// `db` is your SQL client, e.g. a node-postgres Pool

// ── String: cache a user profile for 5 minutes (cache-aside) ──
async function getUserProfile(userId) {
  const cacheKey = `user:${userId}`;

  // 1. Check cache
  const cached = await redis.get(cacheKey);
  if (cached !== null) {
    return JSON.parse(cached); // cache HIT — sub-millisecond
  }

  // 2. Cache miss — query database
  const { rows } = await db.query('SELECT * FROM users WHERE id = $1', [userId]);
  const user = rows[0] ?? null;

  // 3. Populate cache; cache "not found" too, but only briefly
  await redis.set(cacheKey, JSON.stringify(user), 'EX', user ? 300 : 30);
  return user;
}

// ── Hash: store session data ─────────────────────────────────
async function createSession(sessionId, userId, role) {
  const key = `session:${sessionId}`;
  await redis.multi()
    .hset(key, 'user_id', userId, 'role', role, 'created_at', Date.now())
    .expire(key, 3600) // 1-hour TTL, set in the same MULTI
    .exec();
}

async function getSessionRole(sessionId) {
  return redis.hget(`session:${sessionId}`, 'role');
}

// ── Sorted Set: leaderboard ───────────────────────────────────
async function recordScore(userId, points) {
  // ZINCRBY adds to the member's score (ZADD would overwrite it)
  await redis.zincrby('leaderboard:weekly', points, `user:${userId}`);
}

async function getTopTen() {
  // highest score first; ZREVRANGE on Redis < 6.2
  return redis.zrange('leaderboard:weekly', 0, 9, 'REV', 'WITHSCORES');
}

// ── String: fixed-window rate limiting with atomic INCR ──────
async function checkRateLimit(userId, limitPerMinute) {
  const minute = Math.floor(Date.now() / 60000);
  const key = `rate:${userId}:${minute}`;

  // MULTI/EXEC runs INCR and EXPIRE together: a crash between two
  // separate calls could otherwise leave a counter with no TTL
  const [[, count]] = await redis.multi().incr(key).expire(key, 60).exec();
  return count <= limitPerMinute;
}

// ── Distributed lock with an owner token ─────────────────────
async function acquireLock(resource, ttlSeconds) {
  const token = randomUUID(); // proves who owns the lock
  const ok = await redis.set(`lock:${resource}`, token, 'NX', 'EX', ttlSeconds);
  return ok === 'OK' ? token : null; // null = someone else holds it
}

// Release only if we still own it. GET + DEL must be atomic → Lua.
const RELEASE_LOCK = `
if redis.call('GET', KEYS[1]) == ARGV[1] then
  return redis.call('DEL', KEYS[1])
end
return 0`;

async function releaseLock(resource, token) {
  return (await redis.eval(RELEASE_LOCK, 1, `lock:${resource}`, token)) === 1;
}

// Elasticsearch 8/9 via @elastic/elasticsearch (Node.js)
// npm install @elastic/elasticsearch
// (OpenSearch has its own client: @opensearch-project/opensearch)

import { Client } from '@elastic/elasticsearch';
const es = new Client({ node: 'http://localhost:9200' });

// ── 1. Create an index with field mappings ───────────────────
await es.indices.create({
  index: 'products',
  settings: {
    analysis: {
      analyzer: {
        english_custom: {
          type: 'custom',
          tokenizer: 'standard',
          // order matters: lowercase → drop stop words → stem
          filter: ['lowercase', 'stop', 'english_stemmer']
        }
      },
      filter: {
        english_stemmer: { type: 'stemmer', language: 'english' }
      }
    }
  },
  mappings: {
    properties: {
      name:        { type: 'text', analyzer: 'english_custom' },
      description: { type: 'text', analyzer: 'english_custom' },
      category:    { type: 'keyword' },  // exact match, not analysed
      price:       { type: 'float' },
      in_stock:    { type: 'boolean' }
    }
  }
});

// ── 2. Index a document ──────────────────────────────────────
await es.index({
  index: 'products',
  id: 'prod-001',
  document: {
    name: 'Wireless Mechanical Keyboard',
    description: 'Ultra-fast wireless keyboard for gaming and typing',
    category: 'peripherals',
    price: 129.99,
    in_stock: true
  },
  refresh: 'wait_for' // return once the doc is searchable (demo only)
});

// ── 3. Full-text search with filtering ───────────────────────
const result = await es.search({
  index: 'products',
  query: {
    bool: {
      must: [
        {
          multi_match: {
            query: 'wireless keyboard gaming',
            fields: ['name^3', 'description'],  // name boosted 3x at query time
            type: 'best_fields',
            fuzziness: 'AUTO'  // 1 edit for 3–5 chars, 2 edits for longer terms
          }
        }
      ],
      filter: [
        { term: { in_stock: true } },
        { range: { price: { lte: 200 } } }
      ]
    }
  },
  highlight: {
    fields: { description: {} }  // return matched snippets
  },
  size: 10
});

for (const hit of result.hits.hits) {
  console.log(`Score: ${hit._score.toFixed(2)} | ${hit._source.name}`);
}
